	}
	manifest["migrations/sqlite/next_v24_sessions.sql"] = Digest(additive)
	sqls[count] = additive
	return manifest, sqls, nil
}

func upgradeQueueRows(db interface {
	Query(string, ...any) (*sql.Rows, error)
}) (upgradeData, error) {
	rows, e := db.Query("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
	if e != nil {
		return nil, e
	}
	tables := []string{}
	for rows.Next() {
		var name string
		if e = rows.Scan(&name); e != nil {
			rows.Close()
			return nil, e
		}
		tables = append(tables, name)
	}
	e = rows.Err()
	rows.Close()
	if e != nil {
		return nil, e
	}
	result := upgradeData{}
	for _, name := range tables {
		rows, e = db.Query(`SELECT * FROM "` + strings.ReplaceAll(name, `"`, `""`) + `"`)
		if e != nil {
			return nil, e
		}
		cols, e := rows.Columns()
		if e != nil {
			rows.Close()
			return nil, e
		}
		entries := []Object{}
		for rows.Next() {
			values := make([]any, len(cols))
			pointers := make([]any, len(cols))
			for i := range values {
				pointers[i] = &values[i]
			}
			if e = rows.Scan(pointers...); e != nil {
				rows.Close()
				return nil, e
			}
			entry := Object{}
			for i, col := range cols {
				entry[col] = values[i]
			}
			entries = append(entries, entry)
		}
		e = rows.Err()
		rows.Close()
		if e != nil {
			return nil, e
		}
		sort.Slice(entries, func(i, j int) bool { return Hash(entries[i]) < Hash(entries[j]) })
		result[name] = entries
	}
	return result, nil
}
